		if id.Path() != want {
			t.Errorf("Path() = %q, want %q", id.Path(), want)
		}
	})
}

func TestNewCheckpointID(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		wantErr bool
	}{
		{
			name:    "valid 12-char hex",
			input:   "a1b2c3d4e5f6",
			wantErr: false,
		},
		{
			name:    "too short",
			input:   "a1b2c3",
			wantErr: true,
		},
		{
			name:    "too long",
			input:   "a1b2c3d4e5f6789012",
			wantErr: true,
		},
		{
			name:    "non-hex characters",
			input:   "a1b2c3d4e5gg",
			wantErr: true,
		},
		{
			name:    "empty",
			input:   "",
			wantErr: true,
		},
	}

